(function(root){
'use strict';
const A=root.MCAJudge,S=root.GameSymbols,R=root.WCARecords,esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={PB:'政策のチェック',BC:'企業のチェック',BGS:'商品・サービスのチェック',SFM:'海外市場のチェック',AW:'労働者のチェック',SA:'SAの追加チェック',EMPLOYEE:'労働者階級の従業員の選択',SKILLED:'サプライから得る熟練者の選択',SHIFT:'追加シフトの選択'};
const movements=xs=>{const totals=new Map();for(const x of xs){const label=x.series==='policies'?'政策'+x.card:x.card;totals.set(label,(totals.get(label)||0)+x.up);}return totals.size?[...totals].map(([label,n])=>`${label} ＋${n}`).join(' ／ '):'優先順位の移動なし';};
function mount(s,container){if(!root.MiddleClass.hasMiddle(s.records)||!container||!container.querySelector('#classPick')||container.querySelector('#classPick').value!=='Middle')return;container.querySelector('#middleAutomaPreview')?.remove();const panel=document.createElement('details');panel.id='middleAutomaPreview';panel.className='panel middle-automa-preview';const policyItems='<option value="">未指定</option>'+Object.keys(A.DESIRED).map(id=>`<option value="${id}">政策${id}（現在${s.positions[id]}）</option>`).join('');
 panel.innerHTML=`<summary>中産階級オートマの判断を確認</summary><p class="notice">AIカード30枚のボーナス・追加チェック・特殊アクションを含めて確認します。この欄は盤面を変更しません。</p><label>AIカード<select id="middleAutomaCard">${Object.keys(A.CARD_DATA).map(id=>`<option value="${id}">#${id}</option>`).join('')}</select></label><label>確認する内容<select id="middleAutomaKind">${Object.entries(labels).map(([id,label])=>`<option value="${id}">${label}</option>`).join('')}</select></label><div id="middleAutomaPolicies" class="shared-action-fields"><label>AIカードの政策1<select id="middleAutomaPolicy1">${policyItems}</select></label><label>AIカードの政策2<select id="middleAutomaPolicy2">${policyItems}</select></label></div><div id="middleAutomaResult" aria-live="polite"></div><p class="source">出典：添付 middle class.docx ／ <a href="https://hegemonicproject.com/wp-content/uploads/2023/09/Crisis-Control-English-Rulebook-v1.2.pdf" target="_blank" rel="noreferrer">公式C&amp;C v1.2 p.12–13</a>。この確認画面では盤面・手札・履歴を変更しません。</p>`;container.append(panel);
 const q=id=>panel.querySelector('#'+id),show=()=>{const kind=q('middleAutomaKind').value,number=q('middleAutomaCard').value,card=A.CARD_DATA[number],context={records:s.records,positions:s.positions,round:s.round,turn:s.turn,card:{number,...card},policies:s.automaStates?.Middle?.policies||root.WCA.middleInitial().policies,index:0,aside:{policies:{...(s.automaStates?.Middle?.aside.policies||root.WCA.middleInitial().aside.policies),...Object.fromEntries(Object.keys(s.proposals||{}).map(id=>[id,'bill']))}},proposals:s.proposals};q('middleAutomaPolicies').hidden=true;let v,advice;try{if(A.CHECKS.includes(kind)){v=A.evaluate(context,kind);advice=A.evaluateAction(context,kind);}else advice=kind==='EMPLOYEE'?A.employeeAction(context):kind==='SKILLED'?A.skilledAction(context):A.shiftAction(context);q('middleAutomaResult').innerHTML=`${v?`<section class="judge-card ${v.status}"><h3>${esc(labels[kind])}</h3>${v.questions.map(x=>`<p class="notice">${esc(x.label)}</p>`).join('')}${v.warnings.map(x=>`<p class="judge-warning">${esc(x)}</p>`).join('')}${v.status==='ready'?`<p class="judge-result">${esc(movements(v.movements))}</p>`:''}<details><summary>判定理由</summary><ul>${v.reasons.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details></section>`:''}<section class="action-advice ${advice.status}"><h3>${advice.feasible===true?'対象の自動選択':advice.feasible===false?'実行不可':'未登録・未指定'}</h3><p>${S.text(advice.summary)}</p>${advice.targets.length?`<ul>${advice.targets.map(x=>`<li>${S.text(x)}</li>`).join('')}</ul>`:''}${advice.plan?.action==='BC'?R.buildCompanyCard(root.WCA_EXTRA_COMPANIES.find(d=>d.id===advice.plan.id),s.records):''}<details><summary>選択理由</summary><ul>${advice.reasons.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details></section>`;}catch(error){q('middleAutomaResult').innerHTML=`<p class="notice" role="alert">${esc(error.message)}</p>`;}};
 ['middleAutomaKind','middleAutomaCard','middleAutomaPolicy1','middleAutomaPolicy2'].forEach(id=>q(id).onchange=show);show();
}
root.MiddleAutomaUi={mount};
})(globalThis);
